package com.ilker.microsoftreport;
import android.content.*;import org.json.JSONObject;import java.util.*;
public final class StateStore{
 private static final String PREF="ms_store_state_v3";private final SharedPreferences prefs;public StateStore(Context c){prefs=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}public synchronized void saveDashboard(Models.Dashboard d)throws Exception{prefs.edit().putString("dashboard_json",d.toJson()).putLong("last_poll_ms",System.currentTimeMillis()).apply();}public synchronized Models.Dashboard loadDashboard(){String j=prefs.getString("dashboard_json","");if(j.isEmpty())return null;try{return Models.Dashboard.fromJson(j);}catch(Exception e){return null;}}
 public synchronized List<SaleChange> detectChanges(Models.Dashboard d)throws Exception{List<SaleChange>c=new ArrayList<>();String pd=prefs.getString("snapshot_date",""),pj=prefs.getString("snapshot_qty_json","");long pp=prefs.getLong("snapshot_poll_ms",0),now=System.currentTimeMillis();boolean continuous=pp>0&&now-pp<=10*60_000L,same=d.businessDate.equals(pd);Map<String,Integer>prev=new HashMap<>();if(same&&!pj.isEmpty()){JSONObject o=new JSONObject(pj);Iterator<String>it=o.keys();while(it.hasNext()){String k=it.next();prev.put(k,Math.max(0,o.optInt(k,0)));}}boolean baseline=same&&!pj.isEmpty(),midnight=!same&&continuous&&!pd.isEmpty();JSONObject next=new JSONObject();for(Models.AppSale s:d.sales){next.put(s.appId,s.quantity);int before=prev.getOrDefault(s.appId,0);if(midnight)before=0;if((baseline||midnight)&&s.quantity>before)c.add(new SaleChange(s,s.quantity-before));}prefs.edit().putString("snapshot_date",d.businessDate).putString("snapshot_qty_json",next.toString()).putLong("snapshot_poll_ms",now).apply();return c;}
 public static final class SaleChange{public final Models.AppSale sale;public final int delta;SaleChange(Models.AppSale s,int d){sale=s;delta=d;}}
}
